/**
 * Reads asset/boomerang.min.js (~110 KB of minified JS) and writes it as a
 * TypeScript string constant to src/generated/boomerang-source.ts.
 *
 * This allows tsdown to bundle the Boomerang library inline in the npm package
 * so users don't need to host the file separately. At runtime, init.ts imports
 * the string and injects it into the page via script.textContent or returns it
 * from getInlineScript().
 *
 * Runs as a pre-build step: `pnpm generate && tsdown`.
 * The generated file is gitignored since it can always be recreated from the asset.
 *
 * Also validates that the Boomerang version embedded in the .min.js header matches
 * the version declared in package.json's "boomerang" field.
 */

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = resolve(__dirname, "..");

const pkg = JSON.parse(readFileSync(resolve(root, "package.json"), "utf-8"));
const source = readFileSync(resolve(root, "asset/boomerang.min.js"), "utf-8");

const versionMatch = source.match(
	/Boomerang Version:\s*([\d.]+)\s+([0-9a-f]+)/,
);
if (versionMatch) {
	const [, fileVersion, fileCommit] = versionMatch;
	if (
		fileVersion !== pkg.boomerang.version ||
		fileCommit !== pkg.boomerang.commit
	) {
		console.warn(
			`⚠ boomerang.min.js version (${fileVersion} ${fileCommit}) does not match package.json (${pkg.boomerang.version} ${pkg.boomerang.commit}).`,
		);
		console.warn('  Update the "boomerang" field in package.json.');
	}
}

const header = [
	"// This file is auto-generated by scripts/generate-boomerang-source.mjs",
	"// Do not edit manually. Run `pnpm generate` to regenerate.",
	`// Boomerang version: ${pkg.boomerang.version} (${pkg.boomerang.commit})`,
	"",
	"",
].join("\n");

const output = `${header}export const boomerangSource = ${JSON.stringify(source)};\n`;

mkdirSync(resolve(root, "src/generated"), { recursive: true });
writeFileSync(resolve(root, "src/generated/boomerang-source.ts"), output);

console.log("Generated src/generated/boomerang-source.ts");
